from __future__ import annotations

from marshmallow import EXCLUDE, Schema, ValidationError, fields, validates_schema
from marshmallow.validate import OneOf


class _SignupSchema(Schema):
    class Meta:
        unknown = EXCLUDE  # drop unknown keys

    username = fields.String(required=True)
    email = fields.Email(required=True)

    plan = fields.String(
        missing="free",
        validate=OneOf(["free", "pro", "team"], error="Must be one of: free, pro, team."),
    )

    age = fields.Integer(required=False)

    @fields.validates("username")
    def _validate_username(self, value: str) -> None:
        if not value.isalnum():
            raise ValidationError("Username must be alphanumeric.")

    @validates_schema
    def _validate_age(self, data, **kwargs) -> None:
        # Only validate when present (optional field).
        if "age" in data and data["age"] is not None:
            if not (16 <= int(data["age"]) <= 120):
                raise ValidationError({"age": ["Age must be between 16 and 120."]})


class SignupValidationError(ValueError):
    def __init__(self, messages: dict[str, list[str]]):
        super().__init__("invalid signup data")
        self.messages = messages


def validate_signup(data: dict) -> dict:
    """
    Validate and clean signup payload.

    Required: username (alphanumeric), email (valid email)
    Optional: plan (default 'free', one of 'free'|'pro'|'team'), age (16..120)
    Unknown keys are dropped.

    Returns cleaned dict; raises ValueError with .messages on invalid input.
    """
    schema = _SignupSchema()
    try:
        return schema.load(data)
    except ValidationError as err:
        # marshmallow gives messages as dict[str, list[str] | nested], normalize to dict[str, list[str]]
        messages = {}
        for field, field_messages in err.messages.items():
            if isinstance(field_messages, list):
                messages[field] = [str(m) for m in field_messages]
            else:
                # In case of unexpected structure, stringify.
                messages[field] = [str(field_messages)]
        raise SignupValidationError(messages) from None

from __future__ import annotations

from typing import Optional

import pkg_resources


def dependency_report(names: list[str]) -> dict[str, str | None]:
    """
    Map each provided distribution name (keyed exactly as given) to the installed
    distribution version string, matched case-insensitively, or None if not installed.
    """
    result: dict[str, Optional[str]] = {}

    # Build a case-insensitive lookup of installed distributions.
    installed_by_lower: dict[str, str] = {}
    for dist in pkg_resources.working_set:
        try:
            installed_by_lower[dist.project_name.lower()] = dist.version
        except Exception:
            # Be defensive: ignore odd dist entries rather than failing the whole report.
            continue

    for original_name in names:
        if original_name is None:
            # The type says list[str], but keep behavior predictable.
            result[original_name] = None
            continue
        version = installed_by_lower.get(original_name.lower())
        result[original_name] = version

    return result

from __future__ import annotations

import re
from typing import Any, Dict, List

import marshmallow
from marshmallow import Schema, ValidationError, fields


class SignupError(ValueError):
    """
    Raised when signup validation fails.

    The exception exposes a `.messages` attribute as required by the contract.
    """

    def __init__(self, messages: Dict[str, List[str]]):
        super().__init__("Invalid signup data")
        self.messages = messages


_USERNAME_RE = re.compile(r"^[A-Za-z0-9]+$")
# Simple deterministic email regex (no network/DNS)
_EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")

_ALLOWED_PLANS = {"free", "pro", "team"}


class _SignupSchema(Schema):
    class Meta:
        unknown = marshmallow.EXCLUDE  # drop unknown keys

    username = fields.String(required=True)
    email = fields.String(required=True)

    plan = fields.String(load_default="free", required=False)
    age = fields.Integer(required=False, load_default=None, allow_none=True)

    @marshmallow.validates("username")
    def _validate_username(self, value: str) -> None:
        if not _USERNAME_RE.match(value or ""):
            raise ValidationError(["Username must be alphanumeric."])

    @marshmallow.validates("email")
    def _validate_email(self, value: str) -> None:
        if not _EMAIL_RE.match(value or ""):
            raise ValidationError(["Invalid email address."])

    @marshmallow.validates("plan")
    def _validate_plan(self, value: str) -> None:
        if value not in _ALLOWED_PLANS:
            allowed = ", ".join(sorted(_ALLOWED_PLANS))
            raise ValidationError([f"Plan must be one of: {allowed}."])

    @marshmallow.validates("age")
    def _validate_age(self, value: int) -> None:
        if value is None:
            return
        if value < 16 or value > 120:
            raise ValidationError(["Age must be between 16 and 120."])


_schema = _SignupSchema()


def validate_signup(data: dict) -> dict:
    """
    Validate and clean signup input.

    Required:
      - username: alphanumeric string
      - email: valid email address

    Optional:
      - plan: defaults to "free"; must be one of "free", "pro", "team"
      - age: integer, 16..120 inclusive

    Unknown keys are dropped.

    On invalid input, raise ValueError with a `.messages` attribute shaped like:
      {field_name: [error_message, ...], ...}
    """
    try:
        cleaned = _schema.load(data)
        # Ensure default plan always present after load_default
        cleaned.setdefault("plan", "free")
        return cleaned
    except ValidationError as e:
        raw_messages: Any = e.messages

        # Normalize marshmallow messages to the required shape: Dict[str, List[str]]
        messages: Dict[str, List[str]] = {}
        if isinstance(raw_messages, dict):
            for field, msgs in raw_messages.items():
                if isinstance(msgs, list):
                    messages[field] = [str(m) for m in msgs]
                else:
                    messages[field] = [str(msgs)]
        else:
            # Fallback for unexpected message formats
            messages["__all__"] = [str(raw_messages)]

        raise SignupError(messages) from None

from __future__ import annotations

import re
from typing import Any


_USERNAME_RE = re.compile(r"^[A-Za-z0-9]+$")
_EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


class SignupValidationError(ValueError):
    def __init__(self, messages: dict[str, list[str]]):
        super().__init__("Signup validation failed")
        self.messages = messages


def _coerce_int(value: Any) -> int:
    if isinstance(value, bool):
        # bool is a subclass of int; reject explicitly
        raise ValueError("age must be an integer")
    if isinstance(value, int):
        return value
    if isinstance(value, float) and value.is_integer():
        return int(value)
    if isinstance(value, str):
        s = value.strip()
        if not s:
            raise ValueError("age must be an integer")
        return int(s)
    return int(value)  # may raise


def validate_signup(data: dict) -> dict:
    """
    Validate and clean sign-up payload.

    Required:
      - username: alphanumeric string
      - email: basic email format

    Optional:
      - plan: one of {"free","pro","team"} (default "free")
      - age: integer in [16, 120]

    Unknown keys are dropped.

    Raises:
      SignupValidationError (ValueError) with `.messages` dict:
        {field_name: [error_message, ...], ...}
    """
    if not isinstance(data, dict):
        raise SignupValidationError({"_": ["expected a JSON object"]})

    cleaned: dict[str, Any] = {}

    messages: dict[str, list[str]] = {}

    def add_error(field: str, msg: str) -> None:
        messages.setdefault(field, []).append(msg)

    # username
    username = data.get("username", None)
    if username is None:
        add_error("username", "username is required")
    else:
        if not isinstance(username, str) or not _USERNAME_RE.match(username):
            add_error("username", "username must be alphanumeric")

    # email
    email = data.get("email", None)
    if email is None:
        add_error("email", "email is required")
    else:
        if not isinstance(email, str) or not _EMAIL_RE.match(email):
            add_error("email", "invalid email")

    # plan (default "free")
    plan = data.get("plan", "free")
    allowed_plans = {"free", "pro", "team"}
    if plan is None:
        plan = "free"
    if not isinstance(plan, str):
        add_error("plan", "plan must be one of free, pro, team")
    else:
        if plan not in allowed_plans:
            add_error("plan", "plan must be one of free, pro, team")

    # age (optional)
    if "age" in data and data.get("age", None) is not None:
        try:
            age = _coerce_int(data.get("age"))
            if age < 16 or age > 120:
                add_error("age", "age must be between 16 and 120")
            else:
                cleaned["age"] = age
        except Exception:
            add_error("age", "age must be an integer")

    if messages:
        raise SignupValidationError(messages)

    # Fill cleaned values (only if validation succeeded)
    cleaned["username"] = username
    cleaned["email"] = email
    cleaned["plan"] = plan if isinstance(plan, str) else "free"

    # Drop unknown keys by only returning the cleaned fields.
    return cleaned
